// Verified Claude Code release used for declarations generated by CRS.
// This is independent of Anthropic API dates and x-stainless SDK versions.
const DEFAULT_VERSION = '2.1.289'
const USER_AGENT_PATTERN = /^claude-cli\/(\d+\.\d+\.\d+(?:[.\w-]*))\s+\(/i

function getVersion() {
  const version = process.env.CLAUDE_CODE_VERSION || DEFAULT_VERSION
  if (!/^\d+\.\d+\.\d+$/.test(version)) {
    throw new Error('CLAUDE_CODE_VERSION must be a numeric major.minor.patch version')
  }
  return version
}

function getDefaultUserAgent(context = 'external, cli') {
  return `claude-cli/${getVersion()} (${context})`
}

function extractVersion(userAgent) {
  return typeof userAgent === 'string' ? userAgent.match(USER_AGENT_PATTERN)?.[1] || null : null
}

function compareVersions(first, second) {
  const left = first.split('.').map((part) => parseInt(part, 10) || 0)
  const right = second.split('.').map((part) => parseInt(part, 10) || 0)
  for (let index = 0; index < Math.max(left.length, right.length); index++) {
    const difference = (left[index] || 0) - (right[index] || 0)
    if (difference) {
      return Math.sign(difference)
    }
  }
  return 0
}

// Raise only the CC version in outgoing declarations; captured headers stay original.
// Explicit non-CC user agents and all other client metadata remain untouched.
function withMinimumVersion(userAgent) {
  if (!userAgent) {
    return getDefaultUserAgent()
  }
  const version = extractVersion(userAgent)
  if (version && compareVersions(version, getVersion()) < 0) {
    return userAgent.replace(/^(claude-cli\/)[^\s]+/i, `$1${getVersion()}`)
  }
  return userAgent
}

function selectUnifiedUserAgent(cachedUserAgent, clientUserAgent) {
  const cachedVersion = extractVersion(cachedUserAgent)
  const clientVersion = extractVersion(clientUserAgent)
  if (clientVersion && (!cachedVersion || compareVersions(clientVersion, cachedVersion) > 0)) {
    return withMinimumVersion(clientUserAgent)
  }
  return cachedVersion ? withMinimumVersion(cachedUserAgent) : getDefaultUserAgent()
}

module.exports = {
  DEFAULT_VERSION,
  getVersion,
  getDefaultUserAgent,
  extractVersion,
  compareVersions,
  withMinimumVersion,
  selectUnifiedUserAgent
}
